const fs=require('fs'),vm=require('vm'),assert=require('assert');
const storage=new Map(),elements=new Map();const element=id=>{if(!elements.has(id))elements.set(id,{hidden:false,textContent:'',innerHTML:'',dataset:{},onclick:null,setAttribute(){},focus(){},addEventListener(){},getContext(){return {imageSmoothingEnabled:false,fillRect(){}}}});return elements.get(id);};
const sandbox={console,Math,Set,Map,window:{addEventListener(){}},document:{querySelector:element,querySelectorAll:()=>[],addEventListener(){}},localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,String(v)),removeItem:k=>storage.delete(k)},requestAnimationFrame(){}};
vm.createContext(sandbox);vm.runInContext(fs.readFileSync(__dirname+"/character-assets.js","utf8"),sandbox);vm.runInContext(fs.readFileSync(__dirname+'/game.js','utf8'),sandbox);let passes=0;
function test(name,code){try{vm.runInContext('{'+code+'}',sandbox);passes++;console.log('PASS '+name);}catch(e){console.error('FAIL '+name,e);process.exitCode=1;}}
sandbox.assert=assert;
vm.runInContext('audio.init=()=>{};audio.update=()=>{};audio.sfx=()=>{};',sandbox);
test('New title screen does not overwrite a saved run',`assert.equal(localStorage.getItem('pq-save'),null);`);
test('Start, ground collision, and acceleration',`start();for(let i=0;i<40;i++)update();assert.equal(player.y,208);assert(player.ground);keys.add('ArrowRight');for(let i=0;i<20;i++)update();assert(player.x>60);assert.equal(player.vx,1.65);keys.clear();`);
test('K normal jump has variable height and lands',`player.x=40;player.vx=0;keys.add('KeyK');pressed.add('KeyK');let minY=player.y;for(let i=0;i<55;i++){update();minY=Math.min(minY,player.y);}assert(minY<155);assert(player.ground);keys.clear();pressed.add('KeyK');update();let lowY=player.y;for(let i=0;i<45;i++){update();lowY=Math.min(lowY,player.y);}assert(lowY>minY+15);`);
test('Question block releases growth power and is single use',`let t=world.tiles.get('16,10');player.x=258;player.y=190;player.vy=-5;keys.add('KeyK');for(let i=0;i<8;i++)update();keys.clear();assert.equal(t.type,'used');assert.equal(items.length,1);assert.equal(items[0].type,'mushroom');power(items[0]);assert.equal(player.power,1);assert.equal(player.h,24);assert.equal(player.w,18);assert.equal(items.length,0);`);
test('Big hero breaks bricks, collects coins, earns a life',`let t2=world.tiles.get('20,10');bump(t2);assert(!world.tiles.has('20,10'));coins=99;let oldLives=lives;coin(0,0);assert.equal(coins,0);assert.equal(lives,oldLives+1);`);
test('Enemy stomping and turtle shell kicking',`loadStage(0);player.power=0;resizeHero(false);player.inv=0;player.x=200;player.y=185;player.vy=2;world.enemies=[{x:200,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true}];for(let i=0;i<8;i++)update();assert(!world.enemies[0].alive);assert(player.vy<0);player.x=200;player.y=180;player.vy=2;world.enemies=[{x:200,y:208,w:14,h:16,vx:0,vy:0,type:'turtle',alive:true,timer:0}];for(let i=0;i<8;i++)update();assert(world.enemies[0].shell);player.x=world.enemies[0].x-5;player.y=world.enemies[0].y;player.vy=0;update();assert(world.enemies[0].kicked);`);
test('Damage downgrades power, invulnerability protects, pit loses life',`world.enemies=[];player.power=2;resizeHero(true);player.inv=0;hurt();assert.equal(player.power,0);assert.equal(player.h,16);assert(player.inv>0);let before=lives;hurt();assert.equal(lives,before);player.y=310;update();assert(player.dead);assert.equal(lives,before-1);for(let i=0;i<106;i++)update();assert.equal(player.dead,0);`);
test('Fire power creates projectile and star defeats contact enemy',`player.power=2;keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,1);player.star=500;world.enemies=[{x:player.x,y:player.y,w:14,h:12,vx:0,vy:0,type:'grub',alive:true}];update();assert(!world.enemies[0].alive);`);
test('All four levels have valid terrain, safe spawn, reachable gap widths',`for(let n=0;n<4;n++){checkpoint=0;loadStage(n);world.enemies=[];for(let i=0;i<40;i++)update();assert(player.ground,'spawn '+n);assert(player.x<100);let gap=0,maxGap=0;for(let x=0;x<world.length/T;x++){if(!world.tiles.has(x+',14'))gap++;else{maxGap=Math.max(gap,maxGap);gap=0;}}assert(maxGap<=5);assert(world.flagX<world.length-100);assert(world.collect.length>10);}`);
test('Boss requires five hits and guards final flag',`loadStage(3);const boss=world.enemies.find(e=>e.type==='boss');assert.equal(boss.hp,5);player.x=world.flagX;player.y=208;update();assert.equal(finishTime,0);killEnemy(boss);update();assert(finishTime>0);`);
test('Every flag launches fireworks, then the hero enters a pipe and advances automatically',`for(let n=0;n<4;n++){loadStage(n);world.enemies=[];player.x=world.flagX;player.y=208;player.ground=true;update();assert.equal(exitPhase,'approach');assert(fireworks.some(f=>f.kind==='rocket'));let sawSparks=false,sawHop=false,sawSink=false;for(let i=0;i<240&&stage===n&&state==='playing';i++){update();sawSparks ||= fireworks.some(f=>f.kind==='spark');sawHop ||= exitPhase==='hop';sawSink ||= exitPhase==='sink';}assert(sawSparks,'fireworks bloom in world '+n);assert(sawHop,'hero hops onto exit pipe in world '+n);assert(sawSink,'hero enters exit pipe in world '+n);if(n<3){assert.equal(stage,n+1);assert.equal(state,'playing');assert.equal(finishTime,0);}else{assert.equal(state,'victory');assert.equal(localStorage.getItem('pq-save'),null);}}`);
test('Pause preserves simulation and restart resets the run',`start();pause();let x=player.x,t=time;for(let i=0;i<60;i++)update();assert.equal(player.x,x);assert.equal(time,t);activate();assert.equal(state,'playing');score=10000;start();assert.equal(stage,0);assert.equal(score,0);assert.equal(lives,3);`);
test('Home requires confirmation; cancel keeps the run and confirm saves it',`selectCharacter('soldier');start();loadStage(1);player.power=2;player.weapon='lightning';score=4321;pause();assert.equal(state,'paused');assert.equal(document.querySelector('#home').hidden,false);showHomeConfirmation();assert.equal(state,'confirmhome');let x=player.x;for(let i=0;i<30;i++)update();assert.equal(player.x,x);cancelHome();assert.equal(state,'paused');assert.equal(player.power,2);showHomeConfirmation();returnHome();assert.equal(state,'title');assert.equal(document.querySelector('#continue').hidden,false);assert.equal(saved.stage,1);assert.equal(saved.score,4321);assert.equal(saved.weapon,'lightning');start(true);assert.equal(stage,1);assert.equal(player.character,'soldier');assert.equal(player.power,2);assert.equal(player.weapon,'lightning');selectedCharacter='explorer';start();`);

test('Growth scales both dimensions by 1.5 and preserves feet and horizontal center',`start();for(let i=0;i<40;i++)update();let feet=player.y+player.h,center=player.x+player.w/2;let item={x:player.x,y:player.y,type:'mushroom'};items.push(item);power(item);assert.equal(player.h,24);assert.equal(player.w,18);assert.equal(player.y+player.h,feet);assert.equal(player.x+player.w/2,center);player.inv=0;hurt();assert.equal(player.w,12);assert.equal(player.y+player.h,feet);assert.equal(player.x+player.w/2,center);`);
test('A quick Space tap reaches standard bricks without excessive height',`start();world.enemies=[];world.tiles=new Map();for(let x=0;x<30;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});for(let x=10;x<16;x++)world.tiles.set(x+',9',{x:x*16,y:144,w:16,h:16,type:'brick'});player.x=110;player.y=208;player.ground=true;keys.add('ArrowRight');pressed.add('Space');let minimumFeet=224;for(let i=0;i<65;i++){update();minimumFeet=Math.min(minimumFeet,player.y+player.h);}keys.clear();assert(minimumFeet<144);assert(minimumFeet>104);assert.equal(player.y+player.h,144);assert(player.ground);`);
test('Only K permits one midair jump; Space, Up and W cannot add one',`start();world.enemies=[];for(let i=0;i<40;i++)update();pressed.add('Space');update();assert.equal(player.jumps,1);for(let i=0;i<12;i++)update();for(const key of ['Space','ArrowUp','KeyW']){let v=player.vy;pressed.add(key);update();assert.equal(player.jumps,1);assert(player.vy>v);}keys.add('KeyK');pressed.add('KeyK');update();assert.equal(player.jumps,2);assert(player.vy<-5);for(let i=0;i<12;i++)update();const v=player.vy;pressed.add('KeyK');update();assert.equal(player.jumps,2);assert(player.vy>v);keys.clear();for(let i=0;i<120;i++)update();assert(player.ground);assert.equal(player.jumps,0);`);
test('J attack requires the flower, mushroom alone does not unlock attacks',`start();world.enemies=[];keys.add('KeyJ');update();assert.equal(shots.length,0);let item={type:'mushroom',x:player.x,y:player.y};items.push(item);power(item);update();assert.equal(shots.length,0);item={type:'flower',x:player.x,y:player.y};items.push(item);power(item);update();assert.equal(shots.length,1);assert.equal(player.power,2);keys.clear();`);

test('Play opens a character picker and selection starts the requested hero',`state='title';activate();assert.equal(state,'selecting');assert.equal(document.querySelector('#character-picker').hidden,false);selectCharacter('soldier');activate();assert.equal(state,'playing');assert.equal(player.character,'soldier');assert.equal(player.power,0);assert.equal(player.w,14);assert.equal(player.h,24);`);
test('Commando starts unarmed, N unlocks normal bullets, and S gives spread',`keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,0);assert.equal(player.weapon,'none');let it={type:'weaponN',x:player.x,y:player.y};items.push(it);power(it);assert.equal(player.power,1);assert.equal(player.weapon,'rifle');keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,1);assert.equal(shots[0].weapon,'rifle');shots=[];player.fire=0;it={type:'weaponS',x:player.x,y:player.y};items.push(it);power(it);assert.equal(player.power,2);assert.equal(player.weapon,'spread');assert.equal(player.w,14);assert.equal(player.h,24);keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,5);assert(shots.every(s=>s.weapon==='spread'));assert.equal(new Set(shots.map(s=>s.vy)).size,5);`);
test('Commando damage downgrades weapon tier without resizing',`player.inv=0;hurt();assert.equal(player.power,1);assert.equal(player.weapon,'rifle');assert.equal(player.h,24);assert.equal(player.w,14);player.inv=0;hurt();assert.equal(player.power,0);assert.equal(player.weapon,'none');assert.equal(player.h,24);`);
test('L gives piercing lightning and can switch from S at tier three',`start();player.power=1;player.weapon='rifle';let it={type:'weaponL',x:player.x,y:player.y};items.push(it);power(it);assert.equal(player.power,2);assert.equal(player.weapon,'lightning');player.x=100;player.y=200;player.vx=0;player.vy=0;world.tiles=new Map();for(let x=0;x<40;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});world.enemies=[{x:135,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:165,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:195,y:192,w:30,h:32,vx:0,vy:0,type:'boss',alive:true,hp:5,timer:1}];keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'lightning');for(let i=0;i<20;i++)update();assert(!world.enemies[0].alive);assert(!world.enemies[1].alive);assert.equal(world.enemies[2].hp,4);it={type:'weaponS',x:player.x,y:player.y};items.push(it);power(it);assert.equal(player.weapon,'spread');`);
test('Question blocks issue character-specific upgrades and soldier L/S variants',`for(const [name,reward] of [['soldier','weaponN'],['mystic','mysticOrb'],['dora','dorayaki'],['goku','dragonball']]){selectCharacter(name);start();bump(world.tiles.get('16,10'));assert.equal(items[0].type,reward,name);}selectCharacter('soldier');start();const first={type:'weaponN',x:0,y:0};items.push(first);power(first);bump(world.tiles.get('91,10'));assert.equal(items[0].type,'weaponL');bump(world.tiles.get('69,5'));assert.equal(items[1].type,'weaponS');selectCharacter('dora');start();let fake={type:'mushroom',x:0,y:0};items.push(fake);power(fake);assert.equal(player.power,0);`);
test('Character and selected L/S weapon persist through save and stages',`selectCharacter('soldier');start();player.power=2;player.weapon='lightning';save();let run=JSON.parse(localStorage.getItem('pq-save'));assert.equal(run.character,'soldier');assert.equal(run.power,2);assert.equal(run.weapon,'lightning');saved=run;selectedCharacter='explorer';start(true);assert.equal(selectedCharacter,'soldier');assert.equal(player.power,2);assert.equal(player.weapon,'lightning');loadStage(1);assert.equal(player.character,'soldier');assert.equal(player.power,2);assert.equal(player.weapon,'lightning');loadStage(1,true);assert.equal(player.character,'soldier');assert.equal(player.power,0);assert.equal(player.weapon,'none');assert.equal(player.h,24);selectedCharacter='explorer';start();assert.equal(player.h,16);assert.equal(player.character,'explorer');`);

test('First flag is five tiles beyond the last reward block',`const meadow=makeWorld(0);assert.equal(meadow.flagX,190*16);assert.equal(meadow.flagX-meadow.tiles.get('185,8').x,80);`);
test('Mystic upgrades through two mystic orbs without resizing',`selectCharacter('mystic');start();world.enemies=[];for(let i=0;i<40;i++)update();keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,0);let item={type:'mysticOrb',x:0,y:0};items.push(item);power(item);assert.equal(player.power,1);keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'wave');assert.equal(shots[0].vy,0);let waveY=shots[0].y;for(let i=0;i<5;i++)update();assert.equal(shots[0].y,waveY);item={type:'mysticOrb',x:0,y:0};items.push(item);power(item);assert.equal(player.power,2);assert.equal(player.w,14);assert.equal(player.h,24);`);
test('Orange arrow pierces two foes and returns to the thrower',`start();player.power=2;player.x=100;player.y=200;player.vy=0;player.ground=true;world.tiles=new Map();for(let x=0;x<40;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});world.enemies=[{x:150,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:185,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true}];keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'arrow');for(let i=0;i<20;i++)update();assert(world.enemies.every(e=>!e.alive));for(let i=0;i<15;i++)update();assert(shots[0].returning);assert(shots[0].vx<0);for(let i=0;i<90;i++)update();assert.equal(shots.length,0);`);
test('Landing on an arrow freezes it for exactly 300 simulation frames',`start();world.enemies=[];player.power=2;player.x=100;player.y=135;player.vy=1;player.ground=false;shots=[{x:100,y:160,w:28,h:6,vx:3.5,vy:0,life:200,weapon:'arrow',age:10,returning:false,anchored:false,hits:new Set()}];const a=shots[0];update();assert(a.anchored);assert.equal(a.vx,0);assert.equal(a.life,300);assert.equal(player.y+player.h,a.y);assert(player.ground);for(let i=0;i<299;i++)update();assert.equal(shots.length,1);assert.equal(a.life,1);assert.equal(a.x,100);assert.equal(player.y+player.h,160);update();assert.equal(shots.length,0);update();assert(!player.ground);assert(player.y+player.h>160);`);
test('Mystic selection and tier survive save and damage retains fixed size',`player.power=2;save();saved=JSON.parse(localStorage.getItem('pq-save'));selectedCharacter='explorer';start(true);assert.equal(player.character,'mystic');assert.equal(player.power,2);player.inv=0;hurt();assert.equal(player.power,1);assert.equal(player.h,24);assert.equal(player.w,14);`);

test('Arrow return remains on the original horizontal path when the player moves',`selectCharacter('mystic');start();world.enemies=[];world.tiles=new Map();for(let x=0;x<50;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});player.power=2;player.x=100;player.y=200;player.ground=true;keys.add('KeyJ');update();keys.clear();const a=shots[0],originalY=a.y;for(let i=0;i<34;i++)update();assert(a.returning);player.x=250;player.y=80;player.vy=0;for(let i=0;i<8;i++){update();assert.equal(a.y,originalY);assert.equal(a.vy,0);assert(a.vx<0);}for(let i=0;i<50;i++)update();assert.equal(shots.length,0);`);

test('A running K jump can naturally land on the flying arrow',`start();world.enemies=[];world.tiles=new Map();for(let x=0;x<50;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});player.power=2;player.x=100;player.y=200;player.vx=2.75;player.ground=true;keys.add('ArrowRight');keys.add('ShiftLeft');keys.add('KeyJ');update();keys.delete('KeyJ');pressed.add('KeyK');keys.add('KeyK');update();keys.delete('KeyK');const a=shots[0];for(let i=0;i<50&&!a.anchored;i++)update();keys.clear();assert(a.anchored);assert(player.ground);assert.equal(player.y+player.h,a.y);`);

test('Doraemon upgrades with dorayaki from air cannon to super air cannon',`selectCharacter('dora');start();world.enemies=[];for(let i=0;i<40;i++)update();keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,0);const w=player.w,h=player.h;let item={type:'dorayaki',x:0,y:0};items.push(item);power(item);keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'air');assert.equal(shots[0].vy,0);shots=[];player.fire=0;item={type:'dorayaki',x:0,y:0};items.push(item);power(item);keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'superAir');assert(shots[0].w>12);assert(shots[0].h>8);assert.equal(player.w,w);assert.equal(player.h,h);`);
test('Super air kills the first foe, halves damage for the second and cannot hit a third',`start();world.tiles=new Map();for(let x=0;x<50;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});player.power=2;player.x=100;player.y=200;player.ground=true;world.enemies=[{x:150,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:185,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:220,y:192,w:30,h:32,vx:0,vy:0,type:'boss',alive:true,hp:5,timer:0}];keys.add('KeyJ');update();keys.clear();for(let i=0;i<30;i++)update();assert(!world.enemies[0].alive);assert(world.enemies[1].alive);assert.equal(world.enemies[1].hp,.5);assert.equal(world.enemies[2].hp,5);assert.equal(shots.filter(b=>b.weapon==='superAir').length,0);`);
test('Half-damage super air deals 0.5 damage to a second-target boss',`start();world.tiles=new Map();for(let x=0;x<50;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});player.power=2;player.x=100;player.y=200;player.ground=true;world.enemies=[{x:150,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:185,y:192,w:30,h:32,vx:0,vy:0,type:'boss',alive:true,hp:5,timer:0}];keys.add('KeyJ');update();keys.clear();for(let i=0;i<30;i++)update();assert.equal(world.enemies[1].hp,4.5);assert(world.enemies[1].x>185);`);
test('Doraemon tier and character persist; damage retains his body size',`save();saved=JSON.parse(localStorage.getItem('pq-save'));selectedCharacter='explorer';start(true);assert.equal(player.character,'dora');assert.equal(player.power,2);player.inv=0;hurt();assert.equal(player.power,1);assert.equal(player.w,18);assert.equal(player.h,24);loadStage(1,true);assert.equal(player.character,'dora');assert.equal(player.power,0);`);

test('Goku begins without attack and four-star ball unlocks single-target Kamehameha',`selectCharacter('goku');start();world.tiles=new Map();for(let x=0;x<50;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});player.x=100;player.y=200;player.ground=true;world.enemies=[];keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,0);const it={type:'dragonball',x:0,y:0};items.push(it);power(it);world.enemies=[{x:150,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:185,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true}];keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'kame');for(let i=0;i<25;i++)update();assert(!world.enemies[0].alive);assert(world.enemies[1].alive);assert.equal(shots.length,0);`);
test('Super Saiyan Kamehameha deals two boss health points without piercing',`start();player.x=100;player.y=200;player.ground=true;player.power=2;world.tiles=new Map();for(let x=0;x<50;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});world.enemies=[{x:200,y:192,w:30,h:32,vx:0,vy:0,type:'boss',alive:true,hp:5,timer:0},{x:260,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true}];keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'superKame');for(let i=0;i<25;i++)update();assert.equal(world.enemies[0].hp,3);assert(world.enemies[1].alive);assert.equal(shots.filter(s=>s.weapon==='superKame').length,0);`);
test('Goku tier and selection save; damage reverts Super Saiyan to normal size',`save();saved=JSON.parse(localStorage.getItem('pq-save'));selectedCharacter='explorer';start(true);assert.equal(player.character,'goku');assert.equal(player.power,2);player.inv=0;hurt();assert.equal(player.power,1);assert.equal(player.w,14);assert.equal(player.h,24);assert.equal(typeof drawNimbus,'function');`);
test('Nezha starts unarmed, upgrades with lotus, and throws a single-target ring',`selectCharacter('nezha');start();world.enemies=[];world.tiles=new Map();for(let x=0;x<50;x++)world.tiles.set(x+',14',{x:x*16,y:224,w:16,h:16,type:'ground'});player.x=100;player.y=200;player.ground=true;keys.add('KeyJ');update();keys.clear();assert.equal(shots.length,0);assert.equal(rewardFor('mushroom'),'lotus');assert.equal(rewardFor('flower'),'lotus');let it={type:'lotus',x:0,y:0};items.push(it);power(it);assert.equal(player.power,1);assert.equal(player.w,14);assert.equal(player.h,24);world.enemies=[{x:145,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true},{x:190,y:208,w:14,h:12,vx:0,vy:0,type:'grub',alive:true}];keys.add('KeyJ');update();keys.clear();assert.equal(shots[0].weapon,'qiankun');for(let i=0;i<20;i++)update();assert(!world.enemies[0].alive);assert(world.enemies[1].alive);`);
